CREATE TABLE development_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), goal TEXT NOT NULL, stage TEXT NOT NULL CHECK(stage IN ('plan','patch','test','repair','preview','review','complete','blocked')), repairs INTEGER NOT NULL DEFAULT 0 CHECK(repairs BETWEEN 0 AND 2), revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,project_id));
CREATE TABLE development_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, project_id TEXT NOT NULL, stage TEXT NOT NULL, outcome TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(run_id,project_id) REFERENCES development_runs(id,project_id));
